window.JOURNEY_DATA = [
  { id: '1', num: 1, category: 'makkah', icon: '🕋', title: 'قبل البعثة', location: 'مكة المكرمة', date: 'قبل 570م', summary: 'جزيرة العرب قبل الإسلام: من دعوة إبراهيم إلى عام الفيل.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=1', details: '<p class="summary-text">بيت رفع قواعده إبراهيم، وقريش تسود مكة بالرفادة والسقاية وتتاجر شتاءً وصيفًا، في عالم مظلم بين فارس والروم، حتى عام الفيل.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  ثُمَّ إنَّ أَبْرَهَةَ بَنَى الْقُلَّيْسَ بِصَنْعَاءَ، فَبَنَى كَنِيسَةً لَمْ يُرَ مِثْلُهَا فِي زَمَانِهَا بِشَيْءِ مِنْ الْأَرْضِ، ثُمَّ كَتَبَ إلَى النَّجَاشِيِّ: إنِّي قَدْ بَنَيْتُ لَكَ أَيُّهَا الْمَلِكُ كَنِيسَةً لَمْ يُبْنَ مِثْلُهَا لِمَلِكِ كَانَ قَبْلَكَ، وَلَسْتُ بِمُنْتَهٍ حَتَّى أَصْرِفَ إلَيْهَا حَجَّ الْعَرَبِ، فَلَمَّا تَحَدَّثَتْ الْعَرَبُ بِكِتَابِ أَبْرَهَةَ ذَلِكَ إلَى النَّجَاشِيِّ، غَضِبَ رَجُلٌ مِنْ النَّسَأَةِ، أَحَدُ بَنِي فُقَيْمِ ابْن عَدِيِّ بْنِ عَامِرِ بْنِ ثَعْلَبَةَ بْنِ الْحَارِثِ بْنِ مَالِكِ بْنِ كِنَانَةَ بْنِ خُزَيْمَةَ بْنِ مُدْرِكَةَ بْنِ إلْيَاسَ مِنْ مُضَرَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص43 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '2', num: 2, category: 'makkah', icon: '🕋', title: 'المولد النبوي', location: 'مكة المكرمة', date: '570م', summary: 'وُلد النبي ﷺ في مكة يتيم الأب، في عام الفيل.', lat: 21.4230, lng: 39.8260, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=2', details: '<p class="summary-text">وُلد محمد بن عبد الله ﷺ بمكة عام الفيل يوم الاثنين، يتيم الأب.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وُلِدَ رَسُولِ اللَّهِ صلى الله عليه وسلم يَوْمَ الِاثْنَيْنِ، لِاثْنَتَيْ عَشْرَةَ لَيْلَةً خَلَتْ مِنْ شَهْرِ رَبِيعٍ الْأَوَّلِ، عَامَ الْفِيلِ قَالَ ابْنُ إسْحَاقَ: حَدَّثَنِي الْمُطَّلِبُ بْنُ عَبْدِ اللَّهِ بْنِ قَيْسِ بْنِ مَخْرَمَةَ عَنْ أَبِيهِ عَنْ جَدِّهِ قَيْسِ بْنِ مَخْرَمَةَ، قَالَ: وَلَدْتُ أَنَا وَرَسُولُ اللَّهِ صلى الله عليه وسلم عَامَ الْفِيلِ، فَنَحْنُ لِدَانِ .\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص158 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '3', num: 3, category: 'makkah', icon: '🏛️', title: 'الاسترضاع وشق الصدر', location: 'بادية بني سعد', date: '570 - 574م', summary: 'أرضعته حليمة السعدية، وفيها وقعت حادثة شق الصدر.', lat: 21.1000, lng: 40.1000, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=3', details: '<p class="summary-text">أرضعته حليمة السعدية في بادية بني سعد، فنشأ على الفصاحة وصفاء الصحراء، وفيها شُق صدره.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَتْ: فرجعنا بِهِ، فو الله إنَّهُ بَعْدَ مَقْدِمِنَا (بِهِ) بِأَشْهُرِ مَعَ أَخِيهِ لَفِي بَهْمٍ لَنَا خَلْفَ بُيُوتِنَا، إذْ أَتَانَا أَخُوهُ يَشْتَدُّ ، فَقَالَ لِي وَلِأَبِيهِ: ذَاكَ أَخِي الْقُرَشِيُّ قَدْ أَخَذَهُ رَجُلَانِ عَلَيْهِمَا ثِيَابٌ بِيضٌ، فَأَضْجَعَاهُ، فَشَقَّا بَطْنَهُ، فَهُمَا يَسُوطَانِهِ . قَالَتْ: فَخَرَجْتُ أَنَا وَأَبوهُ نَحوه، فَوَجَدنَا قَائِمًا مُنْتَقَعَا وَجْهُهُ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص164 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '4', num: 4, category: 'hijra', icon: '🏛️', title: 'وفاة آمنة', location: 'الأبواء', date: '576م', summary: 'وفاة آمنة بالأبواء في طريق العودة من يثرب.', lat: 23.1044, lng: 39.0558, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=4', details: '<p class="summary-text">خرجت آمنة بابنها إلى أخواله في يثرب، وفي طريق العودة أدركها الموت بالأبواء.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  أَنَّ أُمَّ رَسُولِ اللَّهِ صلى الله عليه وسلم آمِنَةُ تُوُفِّيَتْ وَرَسُولُ اللَّهِ صلى الله عليه وسلم ابْنُ سِتِّ سِنِينَ بِالْأَبْوَاءِ، بَيْنَ مَكَّةَ وَالْمَدِينَةِ، كَانَتْ قَدْ قَدِمَتْ بِهِ عَلَى أَخْوَالِهِ مِنْ بَنِي عَدِيِّ بْنِ النَّجَّارِ، تُزِيرُهُ إيَّاهُمْ، فَمَاتَتْ وَهِيَ رَاجِعَةٌ بِهِ إلَى مَكَّةَ .\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص168 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '5', num: 5, category: 'makkah', icon: '🕋', title: 'كفالة الجد والعم', location: 'مكة المكرمة', date: '576 - 582م', summary: 'كفله جده عبد المطلب ثم عمه أبو طالب.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=5', details: '<p class="summary-text">كفله جده عبد المطلب نحو سنتين، ثم عمه أبو طالب، وعمل في رعي الغنم لأهل مكة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  فَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم بَعْدَ عَبْدِ الْمُطَّلِبِ مَعَ عَمِّهِ أَبِي طَالِبٍ، وَكَانَ عَبْدُ الْمُطَّلِبِ- فِيمَا يَزْعُمُونَ- يُوصِي بِهِ عَمَّهُ أَبَا طَالِبٍ، وَذَلِكَ لِأَنَّ عَبْدَ اللَّهِ أَبَا رَسُولِ اللَّهِ صلى الله عليه وسلم، وَأَبَا طَالِبٍ أَخَوَانِ لِأَبٍ وَأُمٍّ، أُمُّهُمَا فَاطِمَةُ بِنْتُ عَمْرِو بْنِ عَائِذِ بْنِ عَبْدِ بْنِ عِمْرَانَ بْنِ مَخْزُومٍ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص179 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '6', num: 6, category: 'hijra', icon: '🗺️', title: 'الرحلة للشام الأولى', location: 'بُصرى الشام', date: '582م', summary: 'التقى بالراهب بحيرى الذي عرفه بصفات النبوة.', lat: 32.5180, lng: 36.4820, image: 'https://images.unsplash.com/photo-1565552643983-c44917a26ea3?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=6', details: '<p class="summary-text">صحب عمه أبا طالب في تجارته إلى الشام، فعرفه الراهب بحيرى بصفات النبوة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ إنَّ أَبَا طَالِبٍ خَرَجَ فِي رَكْبٍ تَاجِرًا إلَى الشَّامِ، فَلَمَّا تَهَيَّأَ لِلرَّحِيلِ، وَأَجْمَعَ الْمَسِيرَ صَبَّ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم فِيمَا يَزْعُمُونَ- فَرَقَّ لَهُ (أَبُو طَالِبٍ) وَقَالَ: وَاَللَّهِ لَأَخْرُجَنَّ بِهِ مَعِي، وَلَا يُفَارِقُنِي، وَلَا أُفَارِقُهُ أَبَدًا، أَوْ كَمَا قَالَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص180 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '7', num: 7, category: 'makkah', icon: '🕋', title: 'حلف الفضول', location: 'مكة المكرمة', date: '590م', summary: 'شهد النبي حلفاً لنصرة المظلوم في دار ابن جدعان.', lat: 21.4240, lng: 39.8250, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=7', details: '<p class="summary-text">شهد النبي ﷺ حلفًا تعاهدت فيه بطون من قريش على نصرة المظلوم حتى يُرد إليه حقه.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ هِشَامٍ: وَأَمَّا حِلْفُ الْفُضُولِ فَحَدَّثَنِي زِيَادُ بْنُ عَبْدِ اللَّهِ الْبَكَّائِيُّ عَنْ مُحَمَّدِ بْنِ إسْحَاقَ قَالَ: تَدَاعَتْ قَبَائِلُ مِنْ قُرَيْشٍ إلَى حِلْفٍ، فَاجْتَمَعُوا لَهُ فِي دَارِ عَبْدِ اللَّهِ بْنِ جُدْعَانَ ابْن عَمْرِو بْنِ كَعْبِ بْنِ سَعْدِ بْنِ تَيْمِ بْنِ مُرَّةَ بْنِ كَعْبِ بْنِ لُؤَيٍّ، لِشَرَفِهِ وَسِنِّهِ، فَكَانَ حِلْفُهُمْ عِنْدَهُ: بَنُو هَاشِمٍ، وَبَنُو الْمُطَّلِبِ، وَأَسَدُ بْنُ عَبْدِ الْعُزَّى، وَزُهْرَةُ ابْن كِلَابٍ، وَتَيْمُ بْنُ مُرَّةَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص133 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '8', num: 8, category: 'hijra', icon: '🏛️', title: 'تجارة خديجة', location: 'بُصرى الشام', date: '595م', summary: 'خرج في تجارة لخديجة وظهرت أمانته وبركته.', lat: 32.5180, lng: 36.4820, image: 'https://images.unsplash.com/photo-1565552643983-c44917a26ea3?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=8', details: '<p class="summary-text">خرج النبي ﷺ في تجارة لخديجة بنت خويلد إلى الشام، فكانت بداية التعارف بينهما.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَكَانَتْ خَدِيجَةُ بِنْتُ خُوَيْلِدٍ امْرَأَةً تَاجِرَةً ذَاتَ شَرَفٍ وَمَالٍ. تَسْتَأْجِرُ الرِّجَالَ فِي مَالِهَا وَتُضَارِبُهُمْ إيَّاهُ، بِشَيْءٍ تَجْعَلُهُ لَهُمْ، وَكَانَتْ قُرَيْشٌ قَوْمًا تُجَّارًا، فَلَمَّا بَلَغَهَا عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم مَا بَلَغَهَا، مِنْ صَدْقِ حَدِيثِهِ، وَعِظَمِ أَمَانَتِهِ، وَكَرَمِ أَخْلَاقِهِ، بَعَثَتْ إلَيْهِ فَعَرَضَتْ عَلَيْهِ أَنْ يَخْرُجَ فِي مَالٍ لَهَا إلَى الشَّامِ تَاجِرًا، وَتُعْطِيهِ أَفَضْلَ مَا كَانَتْ تُعْطِي غَيْرَهُ مِنْ التُّجَّارِ، مَعَ غُلَامٍ لَهَا يُقَالُ لَهُ مَيْسَرَةَ، فَقَبِلَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص187 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '9', num: 9, category: 'makkah', icon: '🕋', title: 'الزواج من خديجة', location: 'مكة المكرمة', date: '595م', summary: 'تزوج السيدة خديجة وعاش معها 25 سنة.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=9', details: '<p class="summary-text">تزوج النبي ﷺ خديجة بنت خويلد، أقرب نسائه إليه نسبًا، فعاش معها خمسًا وعشرين سنة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ هِشَامٍ: وَأَصْدَقَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم عِشْرِينَ بَكْرَةً، وَكَانَتْ أَوَّلَ امْرَأَةٍ تَزَوَّجَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم، وَلَمْ يَتَزَوَّجْ عَلَيْهَا غَيْرَهَا حَتَّى مَاتَتْ، رضي الله عنها. قَالَ ابْنُ إسْحَاقَ: فَوَلَدَتْ لِرَسُولِ اللَّهِ صلى الله عليه وسلم وَلَدَهُ كُلَّهُمْ إلَّا إبْرَاهِيمَ الْقَاسِمَ، وَبَهْ كَانَ يُكَنَّى صلى الله عليه وسلم، وَالطَّاهِرَ ، وَالطَّيِّبَ، وَزَيْنَبَ، وَرُقَيَّةَ، وَأُمَّ كُلْثُومٍ، وَفَاطِمَةَ، عليهم السلام.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص190 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '10', num: 10, category: 'makkah', icon: '🕋', title: 'بناء الكعبة', location: 'مكة المكرمة', date: '605م', summary: 'أعادت قريش بناء الكعبة واحتكموا للأمين.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=10', details: '<p class="summary-text">أعادت قريش بناء الكعبة، واحتكمت إلى الأمين ﷺ في وضع الحجر الأسود فحلّ النزاع بحكمة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  فَزَعَمَ بَعْضُ أهل الرِّوَايَة: أَن أَبَا أُمِّيَّةَ بْنَ الْمُغِيرَةِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرِ بْنِ مَخْزُوم، وَكَانَ عامئذ أَسَنَّ قُرَيْشٍ كُلِّهَا، قَالَ: يَا مَعْشَرَ قُرَيْشٍ، اجْعَلُوا بَيْنَكُمْ فِيمَا تَخْتَلِفُونَ فِيهِ أَوَّلَ مَنْ يَدْخُلُ مِنْ بَابِ هَذَا الْمَسْجِدِ يَقْضِي بَيْنَكُمْ فِيهِ، فَفَعَلُوا.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص197 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '11', num: 11, category: 'makkah', icon: '🏛️', title: 'التحنث في حراء', location: 'غار حراء', date: 'قبيل 610م', summary: 'حبّب إليه الخلاء فكان يتعبد في غار حراء.', lat: 21.4589, lng: 39.8594, image: 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=11', details: '<p class="summary-text">حُبّب إليه الخلاء، فكان يخلو بغار حراء الليالي ذوات العدد يتعبد ويتفكر.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: فَقَالَ: عُبَيْدٌ- وَأَنَا حَاضِرٌ يُحَدِّثُ عَبْدَ اللَّهِ ابْن الزُّبَيْرِ وَمَنْ عِنْدَهُ مِنْ النَّاسِ-: كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يُجَاوِرُ فِي حِرَاءٍ مِنْ كُلِّ سَنَةٍ شَهْرًا، وَكَانَ ذَلِكَ مِمَّا تَحَنَّثَ بِهِ قُرَيْشٌ فِي الْجَاهِلِيَّة. والتحنث التبرّر.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص235 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '12', num: 12, category: 'makkah', icon: '🏛️', title: 'نزول الوحي', location: 'غار حراء', date: '610م', summary: 'جاءه جبريل فقال: اقرأ، فكانت بداية الرسالة.', lat: 21.4589, lng: 39.8594, image: 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=12', details: '<p class="summary-text">جاءه جبريل في غار حراء فقال: اقرأ، فكانت أول آيات القرآن وبداية الرسالة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: فَجَاءَنِي جِبْرِيلُ، وَأَنَا نَائِمٌ، بِنَمَطٍ مِنْ دِيبَاجٍ فِيهِ كِتَابٌ ، فَقَالَ اقْرَأْ، قَالَ: قُلْتُ: مَا أَقْرَأُ ؟ قَالَ: فَغَتَّنِي بِهِ حَتَّى ظَنَنْتُ أَنَّهُ الْمَوْتُ، ثُمَّ أَرْسَلَنِي فَقَالَ: اقْرَأْ، قَالَ: قُلْتُ: مَا أَقْرَأُ؟ قَالَ: فَغَتَّنِي بِهِ حَتَّى ظَنَنْتُ أَنَّهُ الْمَوْتُ، ثُمَّ أَرْسَلَنِي، فَقَالَ: اقْرَأْ، قَالَ: قُلْتُ: مَاذَا أَقْرَأُ؟\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص236 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '13', num: 13, category: 'makkah', icon: '🕋', title: 'خديجة وورقة', location: 'مكة المكرمة', date: '610م', summary: 'ثبتته خديجة وانطلقت به إلى ورقة بن نوفل.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=13', details: '<p class="summary-text">رجع يرجف فؤاده فقال: زمّلوني، فثبّتته خديجة وانطلقت به إلى ورقة بن نوفل.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  ثُمَّ قَامَتْ فَجَمَعَتْ عَلَيْهَا ثِيَابَهَا، ثُمَّ انْطَلَقَتْ إلَى وَرَقَةَ بْنِ نَوْفَلِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى بْنِ قُصَيٍّ، وَهُوَ ابْنُ عَمِّهَا، وَكَانَ وَرَقَةُ قَدْ تَنَصَّرَ وَقَرَأَ الْكُتُبَ، وَسَمِعَ مِنْ أَهْلِ التَّوْرَاةِ وَالْإِنْجِيلِ، فَأَخْبَرْتُهُ بِمَا أَخْبَرَهَا بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم، أَنَّهُ رَأَى وَسَمِعَ، فَقَالَ وَرَقَةُ بْنُ نَوْفَلٍ: قُدُّوسٌ قُدُّوسٌ ، وَاَلَّذِي نَفْسُ وَرَقَةَ بِيَدِهِ، لَئِنْ كُنْتِ صَدَّقْتِينِي يَا خَدِيجَةُ لَقَدْ جَاءَهُ النَّامُوسُ الْأَكْبَرُ الَّذِي كَانَ يَأْتِي مُوسَى، وَإِنَّهُ لَنَبِيُّ هَذِهِ الْأُمَّةِ، فَقُولِي لَهُ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص238 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '14', num: 14, category: 'makkah', icon: '🕋', title: 'قم فأنذر', location: 'مكة المكرمة', date: '610 - 613م', summary: 'نزل: يا أيها المدثر قم فأنذر، إيذاناً ببدء الدعوة.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=14', details: '<p class="summary-text">فتر الوحي مدة، ثم نزل: «يا أيها المدثر قم فأنذر» إيذانًا ببدء الدعوة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ فَتَرَ الْوَحْيُ عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم فَتْرَةً مِنْ ذَلِكَ، حَتَّى شَقَّ ذَلِكَ عَلَيْهِ فَأَحْزَنَهُ، فَجَاءَهُ جِبْرِيلُ بِسُورَةِ الضُّحَى، يُقْسِمُ لَهُ رَبُّهُ، وَهُوَ الَّذِي أَكْرَمَهُ بِمَا أَكْرَمَهُ بِهِ، مَا وَدَّعَهُ وَمَا قَلَاهُ، فَقَالَ تَعَالَى: وَالضُّحى وَاللَّيْلِ إِذا سَجى.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص241 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '15', num: 15, category: 'makkah', icon: '🕋', title: 'دار الأرقم', location: 'مكة المكرمة', date: '610 - 613م', summary: 'بدأت الدعوة سراً واتخذ دار الأرقم مقراً.', lat: 21.4230, lng: 39.8270, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=15', details: '<p class="summary-text">بدأت الدعوة سرًّا، فآمن السابقون الأولون، واتخذ النبي ﷺ دار الأرقم مقرًّا لتعليمهم.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: فَأَسْلَمَ بِدُعَائِهِ- فِيمَا بَلَغَنِي- عُثْمَانُ بْنُ عَفَّانَ بْنِ أَبِي الْعَاصِ بْنِ أُمَيَّةَ بْنِ عَبْدِ شَمْسِ بْنِ عَبْدِ مَنَافِ بْنِ قُصَيِّ بْنِ كِلَابِ بْنِ مُرَّةَ بْنِ كَعْبِ بْنِ لُؤَيِّ بْنِ غَالِبٍ وَالزُّبَيْرُ بْنُ الْعَوَّامِ بْنِ خُوَيْلِدِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى بْنِ قُصَيِّ بْنِ كِلَابِ بْنِ مُرَّةَ ابْن كَعْبِ بْنِ لُؤَيٍّ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص250 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '16', num: 16, category: 'makkah', icon: '🕋', title: 'إسلام حمزة', location: 'مكة المكرمة', date: 'مبكر', summary: 'أسلم حمزة بن عبد المطلب فكان عزاً للمسلمين.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=16', details: '<p class="summary-text">أسلم حمزة، أعزّ فتى في قريش، غضبًا لابن أخيه، فكان إسلامه عزًّا للمسلمين.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: حَدَّثَنِي رَجُلٌ مِنْ أَسْلَمَ، كَانَ وَاعِيَةً: أَنَّ أَبَا جَهْلٍ مَرَّ بِرَسُولِ اللَّهِ صلى الله عليه وسلم عِنْدَ الصَّفَا، فَآذَاهُ وَشَتَمَهُ، وَنَالَ مِنْهُ بَعْضَ مَا يَكْرَهُ مِنْ الْعَيْبِ لِدِينِهِ، وَالتَّضْعِيفِ لِأَمْرِهِ، فَلَمْ يُكَلِّمْهُ رَسُولُ اللَّهِ صلى الله عليه وسلم، وَمَوْلَاةٌ لِعَبْدِ اللَّهِ بْنِ جُدْعَانَ بْنِ عَمْرِو بْنِ كَعْبِ بْنِ سَعْدِ بْنِ تَيْمِ بْنِ مُرَّةَ فِي مَسْكَنٍ لَهَا تَسْمَعُ ذَلِكَ، ثُمَّ انْصَرَفَ عَنْهُ فَعَمَدَ إلَى نَادٍ مِنْ قُرَيْشٍ عِنْدَ الْكَعْبَةِ، فَجَلَسَ مَعَهُمْ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص291 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '17', num: 17, category: 'makkah', icon: '🏛️', title: 'الجهر بالدعوة', location: 'جبل الصفا', date: '613م', summary: 'صعد الصفا ونادى بطون قريش وأعلن الدعوة.', lat: 21.4235, lng: 39.8265, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=17', details: '<p class="summary-text">نزل «وأنذر عشيرتك الأقربين»، فصعد النبي ﷺ الصفا ونادى بطون قريش وأعلن الدعوة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ دَخَلَ النَّاسُ فِي الْإِسْلَامِ أَرْسَالًا مِنْ الرِّجَالِ وَالنِّسَاءِ، حَتَّى فَشَا ذِكْرُ الْإِسْلَامِ بِمَكَّةَ، وَتُحَدِّثَ بِهِ. ثُمَّ إنَّ اللَّهَ عز وجل أَمَرَ رَسُولَهُ صلى الله عليه وسلم أَنْ يَصْدَعَ بِمَا جَاءَهُ مِنْهُ، وَأَنْ يُبَادِيَ النَّاسَ بِأَمْرِهِ، وَأَنْ يَدْعُوَ إلَيْهِ، وَكَانَ بَيْنَ مَا أَخْفَى رَسُولُ اللَّهِ صلى الله عليه وسلم أَمْرَهُ وَاسْتَتَرَ بِهِ إلَى أَنْ أَمَرَهُ اللَّهُ تَعَالَى بِإِظْهَارِ دِينِهِ ثَلَاثَ سِنِينَ- فِيمَا بَلَغَنِي- مِنْ مَبْعَثِهِ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص262 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '18', num: 18, category: 'makkah', icon: '🕋', title: 'مساومة قريش', location: 'مكة المكرمة', date: '613 - 616م', summary: 'ضغطت قريش وعرضت المال فثبت النبي على دعوته.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=18', details: '<p class="summary-text">ضغطت قريش على أبي طالب ليكفّ ابن أخيه، ثم عرضت المال والملك، فثبت النبي ﷺ على دعوته.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  فَقَالُوا: يَا أَبَا طَالِبٍ، إنَّ ابْنَ أَخِيكَ قَدْ سَبَّ آلِهَتَنَا، وَعَابَ دِينَنَا، وَسَفَّهُ أَحْلَامَنَا، وَضَلَّلَ آبَاءَنَا، فَإِمَّا أَنْ تَكُفَّهُ عَنَّا، وَإِمَّا أَنَّ تُخِلِّي بَيْنَنَا وَبَيْنَهُ، فَإِنَّكَ عَلَى مِثْلِ مَا نَحْنُ عَلَيْهِ مِنْ خِلَافِهِ، فَنَكْفِيكَهُ فَقَالَ لَهُمْ أَبُو طَالِبٍ قَوْلًا رَفِيقًا، وَرَدَّهُمْ رَدًّا جَمِيلًا، فَانْصَرَفُوا عَنْهُ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص265 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '19', num: 19, category: 'makkah', icon: '🕋', title: 'الاضطهاد', location: 'مكة المكرمة', date: '613 - 619م', summary: 'تعذيب المستضعفين كبلال وآل ياسر.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=19', details: '<p class="summary-text">صبّت قريش أذاها على المستضعفين كبلال وآل ياسر، ونال النبي ﷺ نصيبه من السخرية والأذى.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  وَكَانَ بَلَالٌ، مَوْلَى أَبِي بَكْرٍ رضي الله عنهما، لِبَعْضِ بَنِي جُمَحٍ، مُوَلَّدًا مِنْ مُوَلَّدِيهِمْ، وَهُوَ بَلَالُ بْنُ رَبَاحٍ، وَكَانَ اسْمُ أُمِّهِ حَمَامَةَ، وَكَانَ صَادِقَ الْإِسْلَامِ طَاهِرَ الْقَلْبِ، وَكَانَ أُمَيَّةُ بْنُ خَلَفِ بْنِ وَهْبِ بْنِ حُذَافَةَ بْنِ جُمَحٍ يُخْرِجُهُ إذَا حَمِيَتْ الظَّهِيرَةُ، فَيَطْرَحَهُ عَلَى ظَهْرِهِ فِي بَطْحَاءِ مَكَّةَ، ثُمَّ يَأْمُرُ بالصّخرة الْعَظِيمَة فتتوضع عَلَى صَدْرِهِ، ثُمَّ يَقُولُ لَهُ: (لَا وَاَللَّهِ) لَا تَزَالُ هَكَذَا حَتَّى تَمُوتَ، أَوْ تَكْفُرَ بِمُحَمَّدِ، وَتَعْبُدَ اللَّاتَ وَالْعُزَّى، فَيَقُولُ وَهُوَ فِي ذَلِكَ الْبَلَاءِ: أَحَدٌ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص317 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '20', num: 20, category: 'hijra', icon: '🗺️', title: 'الهجرة للحبشة', location: 'أكسوم - الحبشة', date: '615م', summary: 'أول هجرة فراراً بالدين إلى ملك لا يُظلم عنده أحد.', lat: 14.1310, lng: 38.7180, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=20', details: '<p class="summary-text">أذن النبي ﷺ لأصحابه بالهجرة إلى الحبشة، فكانت أول هجرة في الإسلام فرارًا بالدين.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ : فَلَمَّا رَأَى رَسُولُ اللَّهِ صلى الله عليه وسلم مَا يُصِيبُ أَصْحَابَهُ مِنْ الْبَلَاءِ، وَمَا هُوَ فِيهِ مِنْ الْعَافِيَةِ، بِمَكَانِهِ مِنْ اللَّهِ وَمِنْ عَمِّهِ أَبِي طَالِبٍ، وَأَنَّهُ لَا يَقْدِرُ عَلَى أَنْ يَمْنَعَهُمْ مِمَّا هُمْ فِيهِ مِنْ الْبَلَاءِ، قَالَ لَهُمْ: لَوْ خَرَجْتُمْ إلَى أَرْضِ الْحَبَشَةِ فَإِنَّ بِهَا مَلِكًا لَا يُظْلَمُ عِنْدَهُ أَحَدٌ، وَهِيَ أَرْضُ صِدْقٍ، حَتَّى يَجْعَلَ اللَّهُ لَكُمْ فَرَجًا مِمَّا أَنْتُمْ فِيهِ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص321 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '21', num: 21, category: 'hijra', icon: '🏛️', title: 'جعفر والنجاشي', location: 'أكسوم', date: '615 - 616م', summary: 'أفشل جعفر سفارة قريش بكلمته عن الإسلام.', lat: 14.1310, lng: 38.7180, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=21', details: '<p class="summary-text">أرسلت قريش عمرو بن العاص لاسترداد المهاجرين، فأفشل جعفر سفارتهم بكلمته عن الإسلام.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَتْ: ثُمَّ أَرْسَلَ إلَى أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم فَدَعَاهُمْ، فَلَمَّا جَاءَهُمْ رَسُولُهُ اجْتَمَعُوا، ثُمَّ قَالَ بَعْضُهُمْ لِبَعْضِ: مَا تَقُولُونَ لِلرَّجُلِ إذَا جِئْتُمُوهُ؟ قَالُوا: نَقُولُ: وَاَللَّهِ مَا عَلِمْنَا، وَمَا أَمَرَنَا بِهِ نَبِيُّنَا صلى الله عليه وسلم كَائِنًا فِي ذَلِكَ مَا هُوَ كَائِنٌ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص335 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '22', num: 22, category: 'makkah', icon: '🕋', title: 'إسلام عمر', location: 'مكة المكرمة', date: '616م', summary: 'أسلم عمر بن الخطاب فكان إسلامه عِزاً.', lat: 21.4230, lng: 39.8270, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=22', details: '<p class="summary-text">خرج عمر يريد النبي ﷺ متوشحًا سيفه، فدخل الإيمان قلبه عند أخته، وأسلم في دار عند الصفا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَلَمَّا قَدِمَ عَمْرُو بْنُ الْعَاصِ وَعَبْدُ اللَّهِ بْنُ أَبِي رَبِيعَةَ عَلَى قُرَيْشٍ، وَلَمْ يُدْرِكُوا مَا طَلَبُوا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَرَدَّهُمَا النَّجَاشِيُّ بِمَا يَكْرَهُونَ، وَأَسْلَمَ عُمَرُ بْنُ الْخَطَّابِ، وَكَانَ رَجُلًا ذَا شَكِيمَةٍ لَا يُرَامُ مَا وَرَاءَ ظَهْرِهِ، امْتَنَعَ بِهِ أَصْحَابُ رَسُولِ اللَّهِ صلى الله عليه وسلم وَبِحَمْزَةِ حَتَّى عَازُوا قُرَيْشًا ، وَكَانَ عَبْدُ اللَّهِ بْنُ مَسْعُودٍ يَقُولُ: مَا كُنَّا نَقْدِرُ عَلَى أَنْ نُصَلِّيَ عِنْدَ الْكَعْبَةِ، حَتَّى أَسْلَمَ عُمَرُ (بْنُ الْخَطَّابِ) ، فَلَمَّا أَسْلَمَ قَاتَلَ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص342 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '23', num: 23, category: 'makkah', icon: '🕋', title: 'أسئلة اليهود', location: 'مكة المكرمة', date: 'العهد المكي', summary: 'أسئلة امتحان من أحبار يهود ونزول سورة الكهف.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=23', details: '<p class="summary-text">أرسلت قريش إلى أحبار يهود يثرب، فأوصوهم بثلاثة أسئلة امتحانًا للنبي ﷺ، فنزل الجواب قرآنًا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  فَلَمَّا قَالَ لَهُمْ ذَلِكَ النَّضْرُ بْنُ الْحَارِثِ بَعَثُوهُ، وَبَعَثُوا مَعَهُ عُقْبَةَ بْنَ أَبِي مُعَيْطٍ إلَى أَحْبَارِ يَهُودَ بِالْمَدِينَةِ، وَقَالُوا لَهُمَا: سَلَاهُمْ عَنْ مُحَمَّدٍ، وَصِفَا لَهُمْ صِفَتَهُ، وَأَخْبِرَاهُمْ بِقَوْلِهِ، فَإِنَّهُمْ أَهْلُ الْكِتَابِ الْأُوَلِ، وَعِنْدَهُمْ عِلْمٌ لَيْسَ عِنْدَنَا مِنْ عِلْمِ الْأَنْبِيَاءِ، فَخَرَجَا حَتَّى قَدِمَا الْمَدِينَةَ، فَسَأَلَا أَحْبَارَ يَهُودَ عَنْ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَوَصَفَا لَهُمْ أَمْرَهُ، وَأَخْبَرَاهُمْ بِبَعْضِ قَوْلِهِ، وَقَالَا لَهُمْ: إنَّكُمْ أَهْلُ التَّوْرَاةِ، وَقَدْ جِئْنَاكُمْ لِتُخْبِرُونَا عَنْ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص300 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '24', num: 24, category: 'makkah', icon: '🕋', title: 'إسلام الطفيل', location: 'مكة المكرمة', date: 'العهد المكي', summary: 'سمع القرآن فأسلم ودعا قومه في دوس.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=24', details: '<p class="summary-text">حذّرته قريش من سماع النبي ﷺ فحشا أذنيه قطنًا، ثم سمع القرآن فأسلم ودعا قومه.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم، عَلَى مَا يَرَى مِنْ قَوْمِهِ، يَبْذُلُ لَهُمْ النَّصِيحَةَ، وَيَدْعُوهُمْ إلَى النَّجَاةِ مِمَّا هُمْ فِيهِ. وَجَعَلَتْ قُرَيْشٌ، حِينَ مَنَعَهُ اللَّهُ مِنْهُمْ، يُحَذِّرُونَهُ النَّاسَ وَمَنْ قَدِمَ عَلَيْهِمْ مِنْ الْعَرَبِ. وَكَانَ الطُّفَيْلُ بْنُ عَمْرٍو الدَّوْسِيُّ يُحَدِّثُ: أَنَّهُ قَدِمَ مَكَّةَ وَرَسُولُ اللَّهِ صلى الله عليه وسلم بِهَا، فَمَشَى إلَيْهِ رِجَالٌ مِنْ قُرَيْشٍ، وَكَانَ الطُّفَيْلُ رَجُلًا شَرِيفًا شَاعِرًا لَبِيبًا، فَقَالُوا لَهُ: يَا طُفَيْلُ، إنَّكَ قَدِمْتَ بِلَادَنَا، وَهَذَا الرَّجُلُ الَّذِي بَيْنَ أَظْهُرِنَا …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص382 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '25', num: 25, category: 'makkah', icon: '🛡️', title: 'حصار الشعب', location: 'شعب أبي طالب', date: '616 - 619م', summary: 'مقاطعة قريش لبني هاشم وحصارهم في الشعب.', lat: 21.4245, lng: 39.8275, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=25', details: '<p class="summary-text">كتبت قريش صحيفة بمقاطعة بني هاشم وبني المطلب، فحوصروا في الشعب حتى أكلوا ورق الشجر.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: فَلَمَّا رَأَتْ قُرَيْشٌ أَنَّ أَصْحَابَ رَسُولِ اللَّهِ صلى الله عليه وسلم قَدْ نَزَلُوا بَلَدًا أَصَابُوا بِهِ أَمْنًا وَقَرَارًا، وَأَنَّ النَّجَاشِيَّ قَدْ مَنَعَ مَنْ لَجَأَ إلَيْهِ مِنْهُمْ، وَأَنَّ عُمَرَ قَدْ أَسْلَمَ، فَكَانَ هُوَ وَحَمْزَةُ بْنُ عَبْدِ الْمُطَّلِبِ مَعَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَأَصْحَابِهِ، وَجَعَلَ الْإِسْلَامُ يَفْشُو فِي الْقَبَائِلِ، اجْتَمَعُوا وَائْتَمَرُوا (بَيْنَهُمْ) أَنْ يَكْتُبُوا كِتَابًا يَتَعَاقَدُونَ فِيهِ عَلَى بَنِي هَاشِمٍ، وَبَنِيَّ الْمُطَّلِبِ، عَلَى أَنْ لَا يُنْكِحُوا إلَيْهِمْ وَلَا يُنْكَحُوهُمْ، وَلَا يَبِيعُوهُمْ شَيْئًا …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص350 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '26', num: 26, category: 'makkah', icon: '🕋', title: 'عام الحزن', location: 'مكة المكرمة', date: '619م', summary: 'وفاة أبي طالب ثم خديجة رضي الله عنها.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=26', details: '<p class="summary-text">توفي أبو طالب ثم خديجة بعد الخروج من الشعب بقليل، ففقد النبي ﷺ الحامي والسند.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَكَانَ النَّفَرُ الَّذِينَ يُؤْذُونَ رَسُولَ اللَّهِ صلى الله عليه وسلم فِي بَيْتِهِ: أَبَا لَهَبٍ، وَالْحَكَمَ بْنَ الْعَاصِ بْنِ أُمَيَّةَ، وَعُقْبَةَ بْنَ أَبِي مُعَيْطٍ، وَعَدِيَّ بْنَ حَمْرَاءَ الثَّقَفِيَّ، وَابْنَ الْأَصْدَاءِ الْهُذَلِيَّ، وَكَانُوا جِيرَانَهُ لَمْ يُسْلِمْ مِنْهُمْ أَحَدٌ إلَّا الْحَكَمُ بْنُ أَبِي الْعَاصِ، فَكَانَ أَحَدُهُمْ- فِيمَا ذُكِرَ لِي- يَطْرَحُ عَلَيْهِ صلى الله عليه وسلم رَحِمَ الشَّاةِ وَهُوَ يُصَلِّي، وَكَانَ أَحَدُهُمْ يَطْرَحُهَا فِي بُرْمَتِهِ إذَا نُصِبَتْ لَهُ، حَتَّى اتَّخَذَ رَسُولُ اللَّهِ صلى الله عليه وسلم حِجْرًا يَسْتَتِرُ بِهِ مِنْهُمْ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص415 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '27', num: 27, category: 'hijra', icon: '🗺️', title: 'رحلة الطائف', location: 'الطائف', date: '619م', summary: 'خرج يلتمس النصرة فردوه وأغروا به سفهاءهم.', lat: 21.2643, lng: 40.4022, image: 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=27', details: '<p class="summary-text">خرج النبي ﷺ إلى ثقيف يلتمس النصرة، فردّوه وأغروا به سفهاءهم، فعاد إلى مكة في جوار المطعم بن عدي.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَلَمَّا هَلَكَ أَبُو طَالِبٍ نَالَتْ قُرَيْشٌ مِنْ رَسُولِ اللَّهِ صلى الله عليه وسلم مِنْ الْأَذَى مَا لَمْ تَكُنْ تَنَالُ مِنْهُ فِي حَيَاةِ عَمِّهِ أَبِي طَالِبٍ، فَخَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم إلَى الطَّائِفِ، يَلْتَمِسُ النُّصْرَةَ مِنْ ثَقِيفٍ، وَالْمَنَعَةَ بِهِمْ مِنْ قَوْمِهِ، وَرَجَاءَ أَنْ يَقْبَلُوا مِنْهُ مَا جَاءَهُمْ بِهِ مِنْ اللَّهِ عز وجل، فَخَرَجَ إلَيْهِمْ وَحْدَهُ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص419 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '28', num: 28, category: 'makkah', icon: '🏛️', title: 'وفد الجن', location: 'بطن نخلة', date: '619م', summary: 'استمع نفر من الجن للقرآن فآمنوا.', lat: 21.6000, lng: 40.0000, image: 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=28', details: '<p class="summary-text">في طريق العودة من الطائف قام النبي ﷺ يصلي بنخلة، فاستمع إليه نفر من الجن فآمنوا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: ثُمَّ إنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم انْصَرَفَ مِنْ الطَّائِفِ رَاجِعًا إلَى مَكَّةَ، حِينَ يَئِسَ مِنْ خَيْرِ ثَقِيفٍ، حَتَّى إذَا كَانَ بِنَخْلَةَ قَامَ مِنْ جَوْفِ اللَّيْلِ يُصَلِّي، فَمَرَّ بِهِ النَّفَرُ مِنْ الْجِنِّ الَّذِينَ ذَكَرَهُمْ اللَّهُ تبارك وتعالى، وَهُمْ- فِيمَا ذُكِرَ لِي- سَبْعَةُ نَفَرٍ مِنْ جِنِّ أَهْلِ نَصِيبِينَ ، فَاسْتَمَعُوا لَهُ، فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ وَلَّوْا إلَى قَوْمِهِمْ مُنْذِرِينَ، قَدْ آمَنُوا وَأَجَابُوا إلَى مَا سَمِعُوا.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص421 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '29', num: 29, category: 'makkah', icon: '🏛️', title: 'عرض الدعوة', location: 'منى وعكاظ', date: '619 - 621م', summary: 'يتبع القبائل في المواسم بحثاً عن النصرة.', lat: 21.4133, lng: 39.8933, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=29', details: '<p class="summary-text">كان النبي ﷺ يتبع القبائل في منازلها بعكاظ ومجنة ومنى يقول: من يؤويني؟ من ينصرني؟</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ قَدِمَ رَسُولُ اللَّهِ صلى الله عليه وسلم مَكَّةَ، وَقَوْمُهُ أَشَدُّ مَا كَانُوا عَلَيْهِ مِنْ خِلَافِهِ وَفِرَاقِ دِينِهِ، إلَّا قَلِيلًا مُسْتَضْعَفِينَ، مِمَّن آمن بِهِ. فَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَعْرِضُ نَفْسَهُ فِي الْمَوَاسِمِ، إذَا كَانَتْ، عَلَى قَبَائِلِ الْعَرَبِ يَدْعُوهُمْ إلَى اللَّهِ، وَيُخْبِرُهُمْ أَنَّهُ نَبِيٌّ مُرْسَلٌ، وَيَسْأَلُهُمْ أَنْ يُصَدِّقُوهُ وَيَمْنَعُوهُ حَتَّى يُبَيِّنَ (لَهُمْ) اللَّهُ مَا بَعَثَهُ بِهِ .\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص422 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '30', num: 30, category: 'hijra', icon: '🕌', title: 'الإسراء والمعراج', location: 'المسجد الأقصى', date: 'نحو 621م', summary: 'أُسري به ليلًا وفرضت الصلوات الخمس.', lat: 31.7761, lng: 35.2358, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=30', details: '<p class="summary-text">أُسري بالنبي ﷺ ليلًا من المسجد الحرام إلى المسجد الأقصى، ثم عُرج به إلى السماوات العلى وفُرضت الصلاة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ هِشَامٍ: حَدَّثَنَا زِيَادُ بْنُ عَبْدِ اللَّهِ الْبَكَّائِيُّ عَنْ مُحَمَّدِ بْنِ إسْحَاقَ الْمُطَّلِبِيِّ قَالَ: ثُمَّ أُسْرِيَ بِرَسُولِ اللَّهِ صلى الله عليه وسلم مِنْ الْمَسْجِدِ الْحَرَامِ إلَى الْمَسْجِدِ الْأَقْصَى، وَهُوَ بَيْتُ الْمَقْدِسِ مِنْ إيلِيَاء ، وَقَدْ فَشَا الْإِسْلَامُ بِمَكَّةَ فِي قُرَيْشٍ، وَفِي الْقَبَائِلِ كُلِّهَا.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص396 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '31', num: 31, category: 'makkah', icon: '🏛️', title: 'العقبة الأولى', location: 'منى', date: '621م', summary: 'بايعه 12 رجلاً من يثرب وأرسل مصعب معلماً.', lat: 21.4133, lng: 39.8933, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=31', details: '<p class="summary-text">بايع اثنا عشر رجلًا من أهل يثرب النبي ﷺ عند العقبة، وأرسل معهم مصعب بن عمير معلمًا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  حَتَّى إذَا كَانَ الْعَامُ الْمُقْبِلُ وَافَى الْمَوْسِمَ مِنْ الْأَنْصَارِ اثْنَا عَشَرَ رَجُلًا، فَلَقَوْهُ بِالْعَقَبَةِ. (قَالَ) : وَهِيَ الْعَقَبَةُ الْأُولَى، فَبَايَعُوا رَسُولَ اللَّهِ صلى الله عليه وسلم عَلَى بَيْعَةِ النِّسَاءِ ، وَذَلِكَ قَبْلَ أَنْ تُفْتَرَضَ عَلَيْهِمْ الْحَرْبُ. مِنْهُمْ مِنْ بَنِي النَّجَّارِ، ثُمَّ مِنْ بَنِي مَالِكِ بْنِ النَّجَّارِ: أَسْعَدُ بْنُ زُرَارَةَ بْنِ عُدَسَ بْنِ عُبَيْدِ بْنِ ثَعْلَبَةَ بْنِ غَنْمِ بْنِ مَالِكِ بْنِ النَّجَّارِ، وَهُوَ أَبُو أُمَامَةَ، وَعَوْفٌ، وَمُعَاذٌ، ابْنَا الْحَارِثِ بْنِ رِفَاعَةَ بْنِ سَوَادِ بْنِ مَالِكِ بْنِ غَنْمِ بْنِ مَالِكِ بْنِ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص431 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '32', num: 32, category: 'makkah', icon: '🏛️', title: 'العقبة الثانية', location: 'منى', date: '622م', summary: 'بايعه 70 من الأنصار على النصرة والمنعة.', lat: 21.4133, lng: 39.8933, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=32', details: '<p class="summary-text">بايع نحو سبعين من الأنصار النبي ﷺ على النصرة والمنعة، فمهّدت البيعة للهجرة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: فَتَكَلَّمَ رَسُولُ اللَّهِ صلى الله عليه وسلم، فَتَلَا الْقُرْآنَ، وَدَعَا إلَى اللَّهِ، وَرَغَّبَ فِي الْإِسْلَامِ، ثُمَّ قَالَ أُبَايِعُكُمْ عَلَى أَنْ تَمْنَعُونِي مِمَّا تَمْنَعُونَ مِنْهُ نِسَاءَكُمْ وَأَبْنَاءَكُمْ. قَالَ: فَأَخَذَ الْبَرَاءُ بْنُ مَعْرُورٍ بِيَدِهِ، ثُمَّ قَالَ: نَعَمْ، وَاَلَّذِي بَعَثَكَ بِالْحَقِّ (نَبِيًّا) ، لَنَمْنَعَنَّكَ مِمَّا نَمْنَعُ مِنْهُ أُزُرَنَا ، فَبَايِعْنَا يَا رَسُولَ اللَّهِ، فَنَحْنُ وَاَللَّهِ أَبْنَاءُ الْحُرُوبِ، وَأَهْلُ الْحَلْقَةِ ، وَرِثْنَاهَا كَابِرًا (عَنْ كَابِرٍ) .\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص442 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '33', num: 33, category: 'hijra', icon: '🕌', title: 'الهجرة النبوية', location: 'المدينة المنورة', date: '622م', summary: 'وصوله للمدينة وتأسيس الدولة الإسلامية.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=33', details: '<p class="summary-text">خرج النبي ﷺ مع أبي بكر سرًّا، فمكثا في غار ثور ثلاثًا، ثم سلكا طريق الساحل حتى بلغا قباء ثم المدينة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  فَأَتَى جِبْرِيلُ عليه السلام رَسُولَ اللَّهِ صلى الله عليه وسلم، فَقَالَ: لَا تَبِتْ هَذِهِ اللَّيْلَةَ عَلَى فِرَاشِكَ الَّذِي كُنْتَ تَبِيتُ عَلَيْهِ. قَالَ: فَلَمَّا كَانَتْ عَتَمَةٌ مِنْ اللَّيْلِ اجْتَمَعُوا عَلَى بَابِهِ يَرْصُدُونَهُ مَتَى يَنَامُ، فَيَثِبُونَ عَلَيْهِ، فَلَمَّا رَأَى رَسُولُ اللَّهِ صلى الله عليه وسلم مَكَانَهُمْ، قَالَ لِعَلِيِّ بْنِ أَبِي طَالِبٍ: نَمْ عَلَى فِرَاشِي وَتَسَجَّ بِبُرْدِي هَذَا الْحَضْرَمِيِّ الْأَخْضَرِ، فَنَمْ فِيهِ، فَإِنَّهُ لَنْ يَخْلُصَ إلَيْكَ شَيْءٌ تَكْرَهُهُ مِنْهُمْ، وَكَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم يَنَامُ فِي بُرْدِهِ ذَلِكَ إذَا نَامَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص482 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '34', num: 34, category: 'madinah', icon: '🕌', title: 'بناء المسجد', location: 'المدينة المنورة', date: '622 - 623م', summary: 'بناء المسجد والمؤاخاة ووثيقة المدينة.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=34', details: '<p class="summary-text">بنى النبي ﷺ المسجد، وآخى بين المهاجرين والأنصار، وكتب وثيقة تنظم العلاقات في المدينة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: فَأَمَرَ بِهِ رَسُولُ اللَّهِ صلى الله عليه وسلم أَنْ يُبْنَى مَسْجِدًا، وَنَزَلَ رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى أَبِي أَيُّوبَ حَتَّى بَنَى مَسْجِدَهُ وَمَسَاكِنَهُ، فَعَمِلَ فِيهِ رَسُولُ اللَّهِ صلى الله عليه وسلم لِيُرَغِّبَ الْمُسْلِمِينَ فِي الْعَمَلِ فِيهِ، فَعَمِلَ فِيهِ الْمُهَاجِرُونَ وَالْأَنْصَارُ، وَدَأَبُوا فِيهِ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص496 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '35', num: 35, category: 'madinah', icon: '🕌', title: 'تحويل القبلة', location: 'مسجد القبلتين', date: '624م', summary: 'الأمر بالتوجه نحو الكعبة بدلاً من الأقصى.', lat: 24.4839, lng: 39.5816, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=35', details: '<p class="summary-text">بعد نحو ستة عشر أو سبعة عشر شهرًا من الصلاة نحو بيت المقدس، أُمر المسلمون بالتوجه إلى الكعبة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَيُقَالُ: صُرِفَتْ الْقِبْلَةُ فِي شَعْبَانَ عَلَى رَأْسِ ثَمَانِيَةَ عَشَرَ شَهْرًا مِنْ مَقْدَمِ رَسُولِ اللَّهِ صلى الله عليه وسلم الْمَدِينَةَ .\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص606 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '36', num: 36, category: 'madinah', icon: '⚔', title: 'غزوة بدر', location: 'بدر', date: '624م', summary: 'يوم الفرقان ونصر المسلمين الحاسم.', lat: 23.7744, lng: 38.7891, image: 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=36', details: '<p class="summary-text">التقى نحو ثلاثمئة وبضعة عشر مسلمًا بنحو ألف من قريش، فكان يوم الفرقان ونصرًا حاسمًا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ إنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم سَمِعَ بِأَبِي سُفْيَانَ بْنِ حَرْبٍ مُقْبِلًا مِنْ الشَّأْمِ فِي عِيرٍ لِقُرَيْشٍ عَظِيمَةٍ، فِيهَا أَمْوَالٌ لِقُرَيْشِ وَتِجَارَةٌ مِنْ تِجَارَاتِهِمْ وَفِيهَا ثَلَاثُونَ رَجُلًا مِنْ قُرَيْشٍ أَوْ أَرْبَعُونَ، مِنْهُمْ مَخْرَمَةُ بْنُ نَوْفَلِ بْنُ أُهَيْبِ بْنِ عَبْدِ مَنَافِ بْنِ زُهْرَةَ، وَعَمْرُو بْنُ الْعَاصِ بْنِ وَائِلِ بْنِ هِشَامٍ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ1 ص606 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '37', num: 37, category: 'madinah', icon: '⚔', title: 'غزوة أحد', location: 'جبل أحد', date: '625م', summary: 'معركة أحد واستشهاد حمزة رضي الله عنه.', lat: 24.5036, lng: 39.6116, image: 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=37', details: '<p class="summary-text">جاءت قريش تطلب الثأر لبدر، وكان النصر للمسلمين أولًا، ثم تحول حين ترك الرماة مواقعهم.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  لَمَّا أُصِيبَ يَوْمَ بَدْرٍ مِنْ كُفَّارِ قُرَيْشٍ أَصْحَابِ الْقَلِيبِ، وَرَجَعَ فَلُّهُمْ إلَى مَكَّةَ، وَرَجَعَ أَبُو سُفْيَانَ بْنُ حَرْبٍ بِعِيرِهِ، مَشَى عَبْدُ اللَّهِ بْنُ أَبِي رَبِيعَةَ، وَعِكْرِمَةُ بْنُ أَبِي جَهْلٍ، وَصَفْوَانُ بْنُ أُمَيَّةَ، فِي رِجَالٍ مِنْ قُرَيْشٍ، مِمَّنْ أُصِيبَ آبَاؤُهُمْ وَأَبْنَاؤُهُمْ وَإِخْوَانُهُمْ يَوْمَ بَدْرٍ، فَكَلَّمُوا أَبَا سُفْيَانَ بْنَ حَرْبٍ، وَمَنْ كَانَتْ لَهُ فِي تِلْكَ الْعِيرِ مِنْ قُرَيْشٍ تِجَارَةٌ، فَقَالُوا: يَا مَعْشَرَ قُرَيْشٍ، إنَّ مُحَمَّدًا قَدْ وَتَرَكُمْ، وَقَتَلَ خِيَارَكُمْ، فَأَعِينُونَا بِهَذَا الْمَالِ عَلَى حَرْبِهِ، فَلَعَلَّنَا …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص60 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '38', num: 38, category: 'madinah', icon: '🏛️', title: 'الخندق', location: 'جبل سلع', date: '627م', summary: 'تحزب القبائل وحفر الخندق ورد الله للأحزاب.', lat: 24.4833, lng: 39.5933, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=38', details: '<p class="summary-text">تحزبت القبائل في نحو عشرة آلاف لاستئصال المسلمين، فحفروا الخندق، وردّ الله الأحزاب بالريح.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  إنَّهُ كَانَ مِنْ حَدِيثِ الْخَنْدَقِ أَنَّ نَفَرًا مِنْ الْيَهُودِ، مِنْهُمْ: سَلَّامُ بْنُ أَبِي الْحَقِيقِ النَّضْرِيُّ ، وَحُيَيُّ بْنُ أَخْطَبَ النَّضْرِيُّ، وَكِنَانَةُ بْنُ أَبِي الْحَقِيقِ النَّضْرِيُّ، وَهَوْذَةُ بْنُ قَيْسٍ الْوَائِلِيُّ، وَأَبُو عَمَّارٍ الْوَائِلِيُّ، فِي نَفَرٍ مِنْ بَنِي النَّضِيرِ، وَنَفَرٍ مِنْ بَنِي وَائِلٍ، وَهُمْ الَّذِينَ حَزَّبُوا الْأَحْزَابَ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم، خَرَجُوا حَتَّى قَدِمُوا عَلَى قُرَيْشٍ مَكَّةَ، فَدَعَوْهُمْ إلَى حَرْبِ رَسُولِ اللَّهِ صلى الله عليه وسلم، وَقَالُوا: إنَّا سَنَكُونُ مَعَكُمْ عَلَيْهِ، حَتَّى نَسْتَأْصِلَهُ، فَقَالَتْ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص214 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '39', num: 39, category: 'madinah', icon: '📜', title: 'صلح الحديبية', location: 'الحديبية', date: '628م', summary: 'هدنة عشر سنين وبيعة الرضوان.', lat: 21.4420, lng: 39.6380, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=39', details: '<p class="summary-text">خرج النبي ﷺ معتمرًا فصدّته قريش، فكانت بيعة الرضوان ثم صلح عشر سنين سماه القرآن فتحًا مبينًا.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ أَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالْمَدِينَةِ شَهْرَ رَمَضَانَ وَشَوَّالًا، وَخَرَجَ فِي ذِي الْقَعْدَةِ مُعْتَمِرًا، لَا يُرِيدُ حَرْبًا. قَالَ ابْنُ هِشَامٍ: وَاسْتَعْمَلَ عَلَى الْمَدِينَةِ نُمَيْلَةُ بْنُ عَبْدِ اللَّهِ اللَّيْثِيُّ. قَالَ ابْنُ إسْحَاقَ: وَاسْتَنْفَرَ الْعَرَبَ وَمَنْ حَوْلَهُ مِنْ أَهْلِ الْبَوَادِي مِنْ الْأَعْرَابِ لِيَخْرُجُوا مَعَهُ، وَهُوَ يَخْشَى مِنْ قُرَيْشٍ الَّذِي صَنَعُوا، أَنْ يَعْرِضُوا لَهُ بِحَرْبِ أَوْ يَصُدُّوهُ عَنْ الْبَيْتِ، فَأَبْطَأَ عَلَيْهِ كَثِيرٌ مِنْ الْأَعْرَابِ، وَخَرَجَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِمَنْ مَعَهُ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص308 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '40', num: 40, category: 'madinah', icon: '🕌', title: 'مراسلة الملوك', location: 'المدينة المنورة', date: '628م', summary: 'رسائل النبي ﷺ لكسرى وهرقل والنجاشي.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=40', details: '<p class="summary-text">بعد الحديبية كتب النبي ﷺ إلى هرقل وكسرى والنجاشي والمقوقس وغيرهم يدعوهم إلى الإسلام.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ هِشَامٍ: وَقَدْ كَانَ رَسُولُ اللَّهِ صلى الله عليه وسلم بَعَثَ إلَى الْمُلُوكِ رُسُلًا مِنْ أَصْحَابِهِ، وَكَتَبَ مَعَهُمْ إلَيْهِمْ يَدْعُوهُمْ إلَى الْإِسْلَامِ. قَالَ ابْنُ هِشَامٍ: حَدَّثَنِي مَنْ أَثِقُ بِهِ عَنْ أَبِي بَكْرٍ الْهُذَلِيِّ قَالَ: بَلَغَنِي أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم خَرَجَ عَلَى أَصْحَابِهِ ذَاتَ يَوْمٍ بَعْدَ عُمْرَتِهِ الَّتِي صُدَّ عَنْهَا يَوْمَ الْحُدَيْبِيَةِ، فَقَالَ: أَيُّهَا النَّاسُ، إنَّ اللَّهَ قَدْ بَعَثَنِي رَحْمَةً وَكَافَّةً، فَلَا تَخْتَلِفُوا عَلَيَّ كَمَا اخْتَلَفَ الْحَوَارِيُّونَ عَلَى عِيسَى بْنِ مَرْيَمَ، فَقَالَ أَصْحَابُهُ: وَكَيْفَ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص606 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '41', num: 41, category: 'madinah', icon: '⚔', title: 'فتح خيبر', location: 'خيبر', date: '628م', summary: 'سار لحصون خيبر ففتحها.', lat: 25.6969, lng: 39.2947, image: 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=41', details: '<p class="summary-text">سار النبي ﷺ إلى حصون خيبر ففتحها، وأعطى الراية علي بن أبي طالب، وقدم جعفر من الحبشة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ مُحَمَّدُ بْنُ إسْحَاقَ : ثُمَّ أَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالْمَدِينَةِ حِينَ رَجَعَ مِنْ الْحُدَيْبِيَةِ، ذَا الْحَجَّةِ وَبَعْضَ الْمُحَرَّمِ، وَوَلِيَ تِلْكَ الْحَجَّةَ الْمُشْرِكُونَ، ثُمَّ خَرَجَ فِي بَقِيَّةِ الْمُحَرَّمِ إلَى خَيْبَرَ. قَالَ ابْنُ هِشَامٍ: وَاسْتَعْمَلَ عَلَى الْمَدِينَةِ نُمَيْلَةَ بْنَ عَبْدِ اللَّهِ اللَّيْثَيَّ، وَدَفَعَ الرَّايَةَ إلَى عَلِيِّ بْنِ أَبِي طَالِبٍ رضي الله عنه، وَكَانَتْ بَيْضَاءَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص328 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '42', num: 42, category: 'madinah', icon: '⚔', title: 'غزوة مؤتة', location: 'مؤتة', date: '629م', summary: 'مواجهة الروم واستشهاد القادة الثلاثة.', lat: 31.0667, lng: 35.6833, image: 'https://images.unsplash.com/photo-1565552643983-c44917a26ea3?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=42', details: '<p class="summary-text">أول مواجهة مع الروم: استشهد القادة الثلاثة زيد وجعفر وابن رواحة، ثم انحاز خالد بالجيش.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: حَدَّثَنِي مُحَمَّدُ بْنُ جَعْفَرِ بْنِ الزُّبَيْرِ، عَنْ عُرْوَةَ بْنِ الزُّبَيْرِ، قَالَ: بَعَثَ رَسُولُ اللَّهِ صلى الله عليه وسلم بَعْثَةَ إلَى مُؤْتَةَ فِي جُمَادَى الْأُولَى سَنَةَ ثَمَانٍ، وَاسْتَعْمَلَ عَلَيْهِمْ زَيْدَ بْنَ حَارِثَةَ وَقَالَ: إنْ أُصِيبَ زَيْدٌ فَجَعْفَرُ بْنُ أَبِي طَالِبٍ عَلَى النَّاسِ، فَإِنْ أُصِيبَ جَعْفَرٌ فَعَبْدُ اللَّهِ بْنُ رَوَاحَةَ عَلَى النَّاسِ فَتَجَهَّزَ النَّاسُ ثُمَّ تَهَيَّئُوا لِلْخُرُوجِ، وَهُمْ ثَلَاثَةُ آلَافٍ، فَلَمَّا حَضَرَ خُرُوجَهُمْ وَدَّعَ النَّاسُ أُمَرَاءَ رَسُولِ اللَّهِ صلى الله عليه وسلم وَسَلَّمُوا عَلَيْهِمْ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص373 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '43', num: 43, category: 'madinah', icon: '⚔', title: 'فتح مكة', location: 'مكة المكرمة', date: '630م', summary: 'دخول مكة فاتحاً وتحطيم الأصنام.', lat: 21.4225, lng: 39.8262, image: 'https://images.unsplash.com/photo-1584551246679-0daf3d275d0f?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=43', details: '<p class="summary-text">نقضت قريش عهد الحديبية، فسار النبي ﷺ بعشرة آلاف، ودخل مكة فاتحًا وعفا عن أهلها وطهّر البيت من الأصنام.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ أَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم بَعْدَ بَعْثِهِ إلَى مُؤْتَةَ جُمَادَى الْآخِرَةَ وَرَجَبًا. ثُمَّ إنَّ بَنِي بَكْرِ بْنِ عَبْدِ مَنَاةَ بْنِ كِنَانَةَ عَدَتْ عَلَى خُزَاعَةَ، وَهُمْ عَلَى مَاءٍ لَهُمْ بِأَسْفَلِ مَكَّةَ يُقَالُ لَهُ: الْوَتِيرُ، وَكَانَ الَّذِي هَاجَ مَا بَيْنَ بَنِي بَكْرٍ وَخُزَاعَةَ أَنَّ رَجُلًا مِنْ بَنِي الْحَضْرَمِيِّ، وَاسْمُهُ مَالِكُ بْنُ عَبَّادٍ- وَحِلْفُ الْحَضْرَمِيِّ يَوْمَئِذٍ إلَى الْأَسْوَدِ بْنِ رَزْنٍ- خَرَجَ تَاجِرًا، فَلَمَّا تَوَسَّطَ أَرْضَ خُزَاعَةَ، عَدَوْا عَلَيْهِ فَقَتَلُوهُ، وَأَخَذُوا مَالَهُ، فَعَدَتْ بَنُو بَكْرٍ عَلَى …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص389 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '44', num: 44, category: 'madinah', icon: '🏛️', title: 'حنين والطائف', location: 'وادي حنين', date: '630م', summary: 'الانتصار في حنين ثم حصار الطائف.', lat: 21.4670, lng: 40.0000, image: 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=44', details: '<p class="summary-text">اغترّ بعض المسلمين بكثرتهم فانكشفوا أول الأمر، ثم ثبت النبي ﷺ فكان النصر، ثم حوصرت الطائف.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: وَلَمَّا سَمِعَتْ هَوَازِنُ بِرَسُولِ اللَّهِ صلى الله عليه وسلم وَمَا فَتَحَ اللَّهُ عَلَيْهِ مِنْ مَكَّةَ ، جَمَعَهَا مَالِكُ بْنُ عَوْفٍ النَّصْرِيُّ، فَاجْتَمَعَ إلَيْهِ مَعَ هَوَازِنَ ثَقِيفٌ كُلُّهَا، وَاجْتَمَعَتْ نَصْرٌ وَجُشَمٌ كُلُّهَا، وَسَعْدُ بْنُ بَكْرٍ، وَنَاسٌ مِنْ بَنِي هِلَالٍ، وَهُمْ قَلِيلٌ، وَلَمْ يَشْهَدْهَا مِنْ قَيْسِ عَيْلَانَ إلَّا هَؤُلَاءِ، وَغَابَ عَنْهَا فَلَمْ يَحْضُرْهَا مِنْ هَوَازِنَ كَعْبٌ وَلَا كِلَابٌ، وَلَمْ يَشْهَدْهَا مِنْهُمْ أَحَدٌ لَهُ اسْمٌ، وَفِي بَنِي جُشَمٍ دُرَيْدُ بْنُ الصِّمَّةِ شَيْخٌ كَبِيرٌ، لَيْسَ فِيهِ شَيْءٌ إلَّا التَّيَمُّنَ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص437 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '45', num: 45, category: 'madinah', icon: '⚔', title: 'غزوة تبوك', location: 'تبوك', date: '630م', summary: 'جيش العسرة لملاقاة الروم.', lat: 28.3835, lng: 36.5662, image: 'https://images.unsplash.com/photo-1509316785289-025f5b846b35?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=45', details: '<p class="summary-text">خرج النبي ﷺ في نحو ثلاثين ألفًا في حر شديد لملاقاة الروم، فلم يلقَ قتالًا وعقد معاهدات مع أهل الأطراف.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ: حَدَّثَنَا أَبُو مُحَمَّدٍ عَبْدُ الْمَلِكِ بْنِ هِشَامٍ، قَالَ زِيَادُ بْنُ عَبْدِ اللَّهِ الْبَكَّائِيَّ، عَنْ مُحَمَّدِ بْنِ إسْحَاقَ الْمُطَّلِبِيِّ، قَالَ: ثُمَّ أَقَامَ رَسُولُ اللَّهِ صلى الله عليه وسلم بِالْمَدِينَةِ مَا بَيْنَ ذِي الْحَجَّةِ إلَى رَجَبٍ، ثُمَّ أَمَرَ النَّاسَ بِالتَّهَيُّؤِ لِغَزْوِ الرُّومِ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص515 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '46', num: 46, category: 'madinah', icon: '🕌', title: 'عام الوفود', location: 'المدينة المنورة', date: '630 - 631م', summary: 'إقبال القبائل للمدينة لإعلان إسلامها.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=46', details: '<p class="summary-text">أقبلت وفود القبائل من أنحاء الجزيرة إلى المدينة تعلن إسلامها، وحج أبو بكر بالناس.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: لَمَّا افْتَتَحَ رَسُولُ اللَّهِ صلى الله عليه وسلم مَكَّةَ، وَفَرَغَ مِنْ تَبُوكَ، وَأَسْلَمَتْ ثَقِيفٌ وَبَايَعَتْ، ضَرَبَتْ إلَيْهِ وُفُودُ الْعَرَبِ مِنْ كُلِّ وَجْهٍ. قَالَ ابْنُ هِشَامٍ: حَدَّثَنِي أَبُو عُبَيْدَةَ: أَنَّ ذَلِكَ فِي سَنَةِ تِسْعٍ، وَأَنَّهَا كَانَتْ تُسْمَى سَنَةَ الْوُفُودِ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص559 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '47', num: 47, category: 'hijra', icon: '🏛️', title: 'حجة الوداع', location: 'جبل الرحمة', date: '632م', summary: 'خطبة عرفة ونزول: اليوم أكملت لكم دينكم.', lat: 21.3549, lng: 39.9841, image: 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=47', details: '<p class="summary-text">حج النبي ﷺ حجته الوحيدة، وخطب في عرفة خطبته الجامعة، ونزل: «اليوم أكملت لكم دينكم».</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: ثُمَّ مَضَى رَسُولُ اللَّهِ صلى الله عليه وسلم عَلَى حَجِّهِ، فَأَرَى النَّاسَ مَنَاسِكَهُمْ، وَأَعْلَمَهُمْ سُنَنَ حَجِّهِمْ، وَخَطَبَ النَّاسَ خُطْبَتَهُ الَّتِي بَيَّنَ فِيهَا مَا بَيَّنَ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ، ثُمَّ قَالَ: أَيُّهَا النَّاسُ، اسْمَعُوا قَوْلِي، فَإِنِّي لَا أَدْرِي لَعَلِّي لَا أَلْقَاكُمْ بَعْدَ عَامِي هَذَا بِهَذَا الْمَوْقِفِ أَبَدًا، أَيُّهَا النَّاسُ، إنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ عَلَيْكُمْ حَرَامٌ إلَى أَنْ تَلْقَوْا رَبَّكُمْ، كَحُرْمَةِ يَوْمِكُمْ هَذَا، وَكَحُرْمَةِ شَهْرِكُمْ هَذَا، وَإِنَّكُمْ سَتَلْقَوْنَ رَبَّكُمْ، فَيَسْأَلُكُمْ عَنْ …\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص603 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '48', num: 48, category: 'madinah', icon: '🕌', title: 'وفاة النبي ﷺ', location: 'المدينة المنورة', date: '632م', summary: 'انتقاله للرفيق الأعلى عن 63 عاماً.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=48', details: '<p class="summary-text">اشتد المرض بالنبي ﷺ في بيت عائشة، وانتقل إلى الرفيق الأعلى يوم الاثنين عن ثلاث وستين سنة.</p>\n<br>\n<p><strong>مقتطف من المصادر (سيرة ابن هشام):</strong></p>\n<blockquote style="border-right: 3px solid var(--gold); padding-right: 15px; background: #fdfaf3; padding-top: 10px; padding-bottom: 10px; border-radius: 8px; line-height: 1.8;">\n  قَالَ ابْنُ إسْحَاقَ: فَبَيْنَا النَّاسُ عَلَى ذَلِكَ اُبْتُدِئَ رَسُول الله صلى الله عليه وسلم يشكوه الَّذِي قَبَضَهُ اللَّهُ فِيهِ، إلَى مَا أَرَادَ بِهِ مِنْ كَرَامَتِهِ وَرَحْمَتِهِ، فِي لَيَالٍ بَقِينَ مِنْ صَفَرٍ، أَوْ فِي أَوَّلِ شَهْرِ رَبِيعٍ الْأَوَّلِ، فَكَانَ أَوَّلُ مَا اُبْتُدِئَ بِهِ مِنْ ذَلِكَ، فِيمَا ذُكِرَ لِي، أَنَّهُ خَرَجَ إلَى بَقِيعِ الْغَرْقَدِ، مِنْ جَوْفِ اللَّيْلِ، فَاسْتَغْفَرَ لَهُمْ، ثُمَّ رَجَعَ إلَى أَهْلِهِ، فَلَمَّا أَصْبَحَ اُبْتُدِئَ بِوَجَعِهِ مِنْ يَوْمِهِ ذَلِكَ.\n  <br><br><small style="color: var(--muted);">المصدر: سيرة ابن هشام، ت السقا ورفاقه، جـ2 ص642 — المكتبة الشاملة</small>\n</blockquote>' },
  { id: '49', num: 49, category: 'caliphs', icon: '🕌', title: 'الجمع الأول', location: 'المدينة المنورة', date: '632 - 634م', summary: 'جمع أبو بكر القرآن بعد معركة اليمامة.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=49', details: '<p class="summary-text">بعد استشهاد كثير من القرّاء يوم اليمامة، جمع أبو بكر القرآن في صحف واحدة بإشارة عمر، على يد زيد بن ثابت.</p>' },
  { id: '50', num: 50, category: 'caliphs', icon: '🕌', title: 'تعليم الأمصار', location: 'المدينة المنورة', date: '634 - 644م', summary: 'إرسال عمر معلّمي القرآن إلى الشام والأمصار.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=50', details: '<p class="summary-text">صاحب الإشارة بالجمع الأول، حفظ الصحف في خلافته، وأرسل معلّمي القرآن إلى الشام، وجمع الناس في رمضان على قارئ واحد.</p>' },
  { id: '51', num: 51, category: 'caliphs', icon: '🕌', title: 'المصحف العثماني', location: 'المدينة المنورة', date: '644 - 656م', summary: 'نسخ عثمان المصاحف وأرسلها لكل أفق.', lat: 24.4672, lng: 39.6112, image: 'https://images.unsplash.com/photo-1580418827493-f2b22c0a76cb?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=51', details: '<p class="summary-text">لما اختلف الناس في القراءة، نسخ عثمان المصاحف من صحف حفصة بمشورة الصحابة، وأرسل إلى كل أفق بمصحف.</p>' },
  { id: '52', num: 52, category: 'caliphs', icon: '📜', title: 'إقرار المصحف', location: 'الكوفة', date: '656 - 661م', summary: 'إقرار علي بن أبي طالب لجمع المصحف وبقائه محل إجماع.', lat: 32.0292, lng: 44.3986, image: 'https://images.unsplash.com/photo-1565552643983-c44917a26ea3?auto=format&fit=crop&w=1200&q=80', url: 'station.html?event=52', details: '<p class="summary-text">بويع علي بعد مقتل عثمان، ودافع عن جمعه للمصحف وأعلن أنه لو ولي لفعل مثله، فبقي المصحف الإمام محل إجماع.</p>' }
];
